def is_4_colorable(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(4):
            if all(colors[v] != c for v in adj[u]):
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False
    return solve(0)

